import{_ as a,C as o,o as i,c as n,j as t,a as s,E as c,a3 as l}from"./chunks/framework.fntC-tS-.js";const C=JSON.parse('{"title":"Compute","description":"","frontmatter":{"title":"Compute"},"headers":[],"relativePath":"compute/index.md","filePath":"compute/index.md","lastUpdated":1794399607000}'),p={name:"compute/index.md"};function u(h,e,d,m,g,f){const r=o("PageBanner");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"compute",tabindex:"-1"},[s("Compute "),t("a",{class:"header-anchor",href:"#compute","aria-label":'Permalink to "Compute"'},"​")],-1)),c(r,{light:"/images/compute-banner-light.webp",dark:"/images/compute-banner-dark.webp",alt:"Status LEDs and network cables of a switch"}),e[1]||(e[1]=l('<p>Where FGSE researchers can run their computations, and who helps them do it.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="/compute/octopus">Octopus</a>: the GPU cluster operated within FGSE. No scheduler, direct access to the nodes. The <a href="/compute/octopus">how-to</a> covers access, etiquette, SSH and VS Code setup, and programming environments.</li><li><strong>DCSR HPC clusters</strong>: UNIL&#39;s central high-performance computing infrastructure, including a cluster for sensitive data, operated by the <a href="https://www.unil.ch/ci/dcsr-en" target="_blank" rel="noreferrer">Scientific Computing and Research Support Unit (DCSR)</a>. The DCSR also provides virtual workstations and servers for research.</li><li><a href="https://www.cscs.ch" target="_blank" rel="noreferrer">CSCS</a>: the Swiss National Supercomputing Centre. National resources are available through allocation calls.</li></ul><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><ul><li><p><a href="https://www.unil.ch/ci/dcsr-en" target="_blank" rel="noreferrer">Scientific Computing and Research Support Unit, DCSR</a>: the DCSR (Division calcul et soutien à la recherche) provides computation and storage resources to the UNIL community as well as transverse expertise to the faculties and affiliated institutes, from high-performance computing (HPC) programming support to full-stack development consulting.</p></li><li><p><a href="https://wiki.unil.ch/ci/books/research-support/page/high-performance-computing" target="_blank" rel="noreferrer">HPC support to FGSE researchers</a>: a team with HPC expertise provides free support to FGSE researchers on a wide range of topics, including parallelisation and optimisation of codes, benchmarking, algorithm development and implementation, and help with computing-time applications to HPC centres such as CSCS. The team members are <strong>Flavio Calvo</strong> and <strong>Margot Sirdey</strong>. They can be reached at <strong><a href="mailto:research-computing-fgse@unil.ch" target="_blank" rel="noreferrer">research-computing-fgse@unil.ch</a></strong> or during the weekly drop-in session (Geopolis 4631, UNIL). Collaborations in mid- and long-term projects are encouraged. Examples of topics:</p><ul><li>adapting code to the HPC infrastructure (parallelisation, optimisation)</li><li>advice and help with designing and implementing numerical schemes and algorithms</li><li>assistance with the DCSR infrastructure: running on the cluster, on virtual machines, data storage</li><li>automation of data post-processing pipelines</li><li>refactoring code in view of public sharing</li></ul></li><li><p><strong>Geocomputing Centre</strong>: for questions on FGSE compute resources and coordination, write to <a href="mailto:sgc@unil.ch" target="_blank" rel="noreferrer">sgc@unil.ch</a>.</p></li></ul>',5))])}const w=a(p,[["render",u]]);export{C as __pageData,w as default};
